import numpy as np
from scipy.ndimage import label
F=np.load('source_pixels.npz')['rgb'].astype(float)
for typ in ['r','y']:
 xs=[];ys=[];ns=[]
 for t,a in enumerate(F):
  if typ=='r': m=(a[:,:,0]-a[:,:,1]>85)&(a[:,:,0]-a[:,:,2]>65)
