  for i in range(1,n+1):
   y,x=np.where(L==i)
   if len(x)>=3: co.append((len(x),x.mean(),y.mean(),x.min(),y.min(),x.max(),y.max()))
  co=sorted(co,reverse=True)
  c=co[0] if co else (0,np.nan,np.nan,0,0,0,0)
